// seed-contacts-from-sms.mjs
// Seeds construction contacts extracted from Tyler's Mac Messages history into
// the production Firestore `sms_contacts` collection.
//
// Source data: ~/Projects/skyeline-command-center/contacts-extracted.json
//   (generated by the agent SMS-mining task on 2026-06-24)
//
// Behavior:
//   - Only seeds contacts with confidence === 'high' or 'medium'.
//     Low-confidence rows stay in the JSON for manual review.
//   - Idempotent: queries sms_contacts by phoneNumber first; if a doc with that
//     phoneNumber already exists, the record is SKIPPED (no overwrite).
//   - Dry-run by default. Pass --commit to actually write to Firestore.
//
// Usage:
//   node seed-contacts-from-sms.mjs                # dry run, prints plan
//   node seed-contacts-from-sms.mjs --commit       # actually writes
//   node seed-contacts-from-sms.mjs --limit 5      # only first 5
//   node seed-contacts-from-sms.mjs --role SUB     # filter by role
//   node seed-contacts-from-sms.mjs --include-low  # also include low confidence

import { initializeApp, cert } from 'firebase-admin/app';
import { getFirestore, FieldValue } from 'firebase-admin/firestore';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const EXTRACT_PATH = resolve(
  __dirname,
  '../../skyeline-command-center/contacts-extracted.json'
);

// ---- CLI args ----
const args = process.argv.slice(2);
const COMMIT = args.includes('--commit');
const INCLUDE_LOW = args.includes('--include-low');
const limitArg = args.find((a) => a.startsWith('--limit'));
const LIMIT = limitArg
  ? parseInt(limitArg.split('=')[1] ?? args[args.indexOf(limitArg) + 1] ?? '0', 10) || null
  : null;
const roleArg = args.find((a) => a.startsWith('--role'));
const ROLE_FILTER = roleArg
  ? roleArg.split('=')[1] ?? args[args.indexOf(roleArg) + 1]
  : null;

// ---- Load extracted contacts ----
const raw = JSON.parse(readFileSync(EXTRACT_PATH, 'utf8'));
console.log(`📂 Loaded ${raw.contacts.length} contacts from ${EXTRACT_PATH}`);
console.log(`   extractedAt: ${raw.extractedAt}`);

const allowedConfidence = INCLUDE_LOW
  ? new Set(['high', 'medium', 'low'])
  : new Set(['high', 'medium']);

let candidates = raw.contacts.filter((c) => allowedConfidence.has(c.confidence));
if (ROLE_FILTER) candidates = candidates.filter((c) => c.role === ROLE_FILTER);
if (LIMIT) candidates = candidates.slice(0, LIMIT);

console.log(
  `🎯 ${candidates.length} candidates after filter (` +
    `confidence=${[...allowedConfidence].join('|')}` +
    `${ROLE_FILTER ? `, role=${ROLE_FILTER}` : ''}` +
    `${LIMIT ? `, limit=${LIMIT}` : ''})`
);

// ---- Initialize Firestore ----
// Prefer a local service account JSON if present (avoids firebase login --reauth).
// Falls back to Application Default Credentials (ADC) when running in CI / Cloud.
import { existsSync } from 'node:fs';
import { createRequire } from 'node:module';
const _require = createRequire(import.meta.url);
const SA_PATH = new URL('../../service-account.json', import.meta.url).pathname;
if (existsSync(SA_PATH)) {
  const { cert } = await import('firebase-admin/app');
  const serviceAccount = _require(SA_PATH);
  initializeApp({ credential: cert(serviceAccount) });
} else {
  initializeApp({ projectId: 'skyelineos' });
}
const db = getFirestore();

// ---- Helper: clean displayed name (strip "(stucco, gutters)" notes) ----
function cleanName(name) {
  if (!name) return null;
  // Remove parenthetical notes
  let cleaned = name.replace(/\s*\([^)]*\)/g, '').trim();
  // Strip "(inferred)" marker
  cleaned = cleaned.replace(/\s*\(inferred\)\s*$/i, '').trim();
  return cleaned || name; // fall back to raw if cleaning emptied it
}

// ---- Build Firestore doc from extracted contact ----
function buildDoc(c) {
  return {
    name: cleanName(c.name),
    phoneNumber: c.phoneNumber,
    role: c.role, // SUB | CLIENT | INTERNAL | VENDOR
    trade: c.trade, // FRAMER | ELECTRICIAN | ... | UNKNOWN
    preferredLanguage: c.preferredLanguage, // 'en' | 'es'
    projectNames: c.projectNames || [],
    projectIds: [], // populated later when projects are seeded
    // Provenance / debugging
    source: 'sms_extract_v1',
    sourceConfidence: c.confidence,
    sourceNameOrigin: c.nameSource,
    sourceLastMessageDate: c.lastMessageDate || null,
    sourceMessageCount: c.totalMessages || 0,
    sourceRecentSample: c.recentMessageSample || null,
    createdAt: FieldValue.serverTimestamp(),
  };
}

// ---- Main ----
const summary = {
  toCreate: [],
  toSkip: [],
  errors: [],
};

for (const c of candidates) {
  try {
    const existing = await db
      .collection('sms_contacts')
      .where('phoneNumber', '==', c.phoneNumber)
      .limit(1)
      .get();
    if (!existing.empty) {
      summary.toSkip.push({ phone: c.phoneNumber, reason: 'already_exists', id: existing.docs[0].id });
      continue;
    }
    const doc = buildDoc(c);
    summary.toCreate.push(doc);
  } catch (e) {
    summary.errors.push({ phone: c.phoneNumber, err: e.message });
  }
}

console.log('');
console.log(`📊 Plan:`);
console.log(`   to create: ${summary.toCreate.length}`);
console.log(`   to skip (already exists): ${summary.toSkip.length}`);
console.log(`   errors during lookup: ${summary.errors.length}`);

// Show a sample of what would be created
if (summary.toCreate.length) {
  console.log('');
  console.log('🔎 Sample (first 5 to create):');
  for (const d of summary.toCreate.slice(0, 5)) {
    console.log(
      `   ${d.phoneNumber}  ${d.name?.padEnd(28) || '(no name)'.padEnd(28)} ${d.role}/${d.trade}  lang=${d.preferredLanguage}  conf=${d.sourceConfidence}`
    );
  }
}

if (!COMMIT) {
  console.log('');
  console.log('💡 Dry run complete. Pass --commit to actually write to Firestore.');
  process.exit(0);
}

// ---- Commit phase ----
console.log('');
console.log('🚀 Committing to Firestore...');
let created = 0;
let failed = 0;
// Batches of 400 (Firestore limit 500; safety margin)
const BATCH_SIZE = 400;
for (let i = 0; i < summary.toCreate.length; i += BATCH_SIZE) {
  const slice = summary.toCreate.slice(i, i + BATCH_SIZE);
  const batch = db.batch();
  const refs = slice.map(() => db.collection('sms_contacts').doc());
  slice.forEach((doc, idx) => batch.set(refs[idx], doc));
  try {
    await batch.commit();
    created += slice.length;
    console.log(`   ✅ batch ${Math.floor(i / BATCH_SIZE) + 1}: wrote ${slice.length}`);
  } catch (e) {
    failed += slice.length;
    console.error(`   ❌ batch ${Math.floor(i / BATCH_SIZE) + 1} failed:`, e.message);
  }
}

console.log('');
console.log(`✅ Done. Created: ${created}. Failed: ${failed}. Skipped (existing): ${summary.toSkip.length}.`);
process.exit(failed ? 1 : 0);
